-- portee: production
-- ============================================================================
-- Plan de culture · Les préconisations d'apport N-P-K, par légume
--
-- CE QUE C'EST, ET CE QUE CE N'EST PAS
--
-- Une préconisation d'apport en kg par hectare, pour les 59 légumes du plan.
-- À ne pas confondre avec les EXPORTATIONS déjà en base sur l'itinéraire :
--   · exportation = ce que le produit récolté retire de la parcelle ;
--   · préconisation = ce qu'il est conseillé d'apporter.
-- Les deux cohabitent exprès. Le jour où les analyses de sol entreront, le
-- vrai bilan se fera entre les trois : préconisation, exportation, fourniture
-- du sol. Aujourd'hui la troisième manque, donc ceci est un INDICATEUR.
--
-- ⚠️ AUCUNE DE CES VALEURS NE DÉDUIT LA FOURNITURE DU SOL. Chaque source le
-- dit explicitement. Ce ne sont pas des doses à épandre les yeux fermés.
--
-- LA MÉTHODE DE LA SOURCE, et pourquoi elle est contrôlable : chaque ligne
-- part d'une référence publiée (Agroscope PRIF module 10 pour 41 lignes,
-- CTIFL via Sud & Bio / CIVAM Bio 66 pour 13, GRAB, Chambres d'agriculture)
-- et la met au prorata du rendement RÉEL de Chants de la Terre :
--
--     besoin = référence × (notre rendement / rendement de référence)
--
-- VÉRIFIÉ AVANT CHARGEMENT : le prorata a été recalculé ligne à ligne depuis
-- la référence citée dans la source. 58 lignes vérifiables, 58 exactes, zéro
-- écart. Les 59 noms de légume tombent sur un légume existant.
--
-- CONSÉQUENCE À CONNAÎTRE : le prorata propage nos propres rendements. Là où
-- le rendement est douteux, la préconisation l'est autant — pain de sucre,
-- Choggia, chou chinois, scarole reposent sur des rendements à la pièce que
-- nous n'avons pas validés.
--
-- LES LÉGUMINEUSES sont traitées correctement : l'azote est rabattu parce que
-- la fixation symbiotique est déjà intégrée dans la référence. Petits pois et
-- pois mange-tout à 0, haricot nain 24, haricot grain 30. Pas de double
-- déduction.
--
-- DEUX RÉSERVES NOMMÉES :
--   · patate douce : INCONNU sur les trois. La source publie des apports
--     conditionnels selon le précédent, pas un besoin brut. Rien n'est écrit.
--   · pastèque, 240/240/400 : prorata d'une référence CONVENTIONNELLE
--     TROPICALE (Chambre d'agriculture de Martinique). Le transfert en plaine
--     d'Alsace est incertain, la source le dit. À regarder avant usage.
--
-- `coalesce` partout : une valeur corrigée à la main n'est jamais écrasée.
-- ============================================================================

alter table production.legume
  add column if not exists besoin_n_kg_ha                 numeric(8,2) check (besoin_n_kg_ha >= 0),
  add column if not exists besoin_p2o5_kg_ha              numeric(8,2) check (besoin_p2o5_kg_ha >= 0),
  add column if not exists besoin_k2o_kg_ha               numeric(8,2) check (besoin_k2o_kg_ha >= 0),
  add column if not exists besoin_rendement_reference_t_ha numeric(8,3) check (besoin_rendement_reference_t_ha > 0),
  add column if not exists besoin_fiabilite               text,
  add column if not exists besoin_source                  text,
  add column if not exists besoin_note                    text;

comment on column production.legume.besoin_n_kg_ha is
  'Preconisation d''APPORT en kg N/ha. Ne deduit PAS la fourniture du sol. A distinguer de itineraire.export_n_kg_par_tonne, qui est ce que la recolte retire.';
comment on column production.legume.besoin_rendement_reference_t_ha is
  'Le niveau de rendement auquel la preconisation correspond. Si le rendement reel s''en ecarte, la preconisation est a revoir.';

-- ------------------------------------------------------------- le chargement
update production.legume l set
  besoin_n_kg_ha                  = coalesce(l.besoin_n_kg_ha, v.n),
  besoin_p2o5_kg_ha               = coalesce(l.besoin_p2o5_kg_ha, v.p),
  besoin_k2o_kg_ha                = coalesce(l.besoin_k2o_kg_ha, v.k),
  besoin_rendement_reference_t_ha = coalesce(l.besoin_rendement_reference_t_ha, v.niveau),
  besoin_fiabilite                = coalesce(l.besoin_fiabilite, v.fiabilite),
  besoin_source                   = coalesce(l.besoin_source, v.source),
  besoin_note                     = coalesce(l.besoin_note, v.note)
