-- ----------------------------------------------------------------- le contrôle
--  On compte le report, pas la cible intacte : ces valeurs sont faites pour
--  être corrigées quand les analyses de sol arriveront.
do $$
declare n integer; m numeric;
begin
  select count(*) into n from production.legume where besoin_source is not null;
  if n < 59 then raise exception 'Preconisations chargees : % sur 59 attendues', n; end if;

  select count(*) into n from production.legume where besoin_n_kg_ha is not null;
  if n < 58 then raise exception 'Azote renseigne : % sur 58 attendus (patate douce reste INCONNU)', n; end if;

  --  Les légumineuses ne doivent jamais porter un azote d'apport élevé :
  --  la fixation est déjà dans la référence. Un chiffre haut signalerait une
  --  double comptabilisation.
  select count(*) into n from production.legume l
    join production.famille_botanique f on f.id = l.famille_botanique_id
   where f.nom = 'légumineuse' and l.besoin_n_kg_ha > 60;
  if n > 0 then
    raise exception '% legumineuse(s) avec un apport d''azote > 60 kg/ha : la fixation est comptee deux fois', n;
  end if;

  --  Le niveau de rendement de référence doit exister partout où un besoin
  --  est posé : sans lui, le chiffre n'est pas interprétable.
  select count(*) into n from production.legume
   where besoin_n_kg_ha is not null and besoin_rendement_reference_t_ha is null;
  if n > 0 then raise exception '% besoins sans niveau de rendement de reference', n; end if;

  select round(avg(besoin_n_kg_ha)) into m from production.legume where besoin_n_kg_ha is not null;
  raise notice 'Preconisations N-P-K en place · 59 legumes, 58 chiffres, azote moyen % kg/ha. Fourniture du sol NON deduite.', m;
end $$;
